import "io" for File

// realPath normalizes ./a/./b/../b/c patterns using an existing file
var normalized = File.realPath("test/io/file/../../io/file/./file.txt")
System.print(normalized.contains("..")) // expect: false
System.print(normalized.contains("./")) // expect: false
System.print(normalized.endsWith("file.txt")) // expect: true
